#!/usr/bin/env python3
"""Generates src/render/castRegistry.ts (static require()s) from assets/sprites/*/manifest.json."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
SPRITES = ROOT / "assets/sprites"
OUT = ROOT / "src/render/castRegistry.ts"
PREFERRED_ORDER = ["idle", "pop", "hop", "wave", "surprised", "celebrate", "sad"]


def main() -> None:
    chars = sorted(p.parent.name for p in SPRITES.glob("*/manifest.json"))
    lines = [
        "// GENERATED by scripts/assets/buildRegistry.py - do not edit.",
        "import type { CharacterSheet } from './sprites';",
        "",
        "export const CAST: Record<string, CharacterSheet> = {",
    ]
    for name in chars:
        m = json.loads((SPRITES / name / "manifest.json").read_text())
        clips = sorted(m["clips"], key=lambda c: (PREFERRED_ORDER.index(c) if c in PREFERRED_ORDER else 99, c))
        assert clips[0] == "idle", f"{name}: idle clip must exist and be first"
        lines.append(f"  {name}: {{")
        lines.append(f"    frameWidth: {m['frameWidth']},")
        lines.append(f"    frameHeight: {m['frameHeight']},")
        lines.append(f"    fps: {m['fps']},")
        lines.append(f"    order: {json.dumps(clips)},")
        lines.append(f"    clips: {json.dumps({c: m['clips'][c] for c in clips})},")
        lines.append("    sources: {")
        for c in clips:
            lines.append(f"      {c}: require('../../assets/sprites/{name}/{c}.webp'),")
        lines.append("    },")
        lines.append("  },")
    lines.append("};")
    lines.append("")
    lines.append(f"export const CAST_IDS = {json.dumps(chars)} as const;")
    OUT.write_text("\n".join(lines) + "\n")
    print(f"wrote {OUT.relative_to(ROOT)} ({len(chars)} characters)")


if __name__ == "__main__":
    main()
